const STORAGE_KEY = "habitTracker";

const els = {
  form: app.querySelector('[data-role="habit-form"]'),
  nameInput: app.querySelector('[data-role="habit-name"]'),
  formError: app.querySelector('[data-role="form-error"]'),
  list: app.querySelector('[data-role="habit-list"]'),
  emptyHint: app.querySelector('[data-role="empty-hint"]'),
  listCount: app.querySelector('[data-role="list-count"]'),
  statDone: app.querySelector('[data-role="stat-done"]'),
  statTotal: app.querySelector('[data-role="stat-total"]'),
  statRate: app.querySelector('[data-role="stat-rate"]'),
  todayText: app.querySelector('[data-role="today-text"]'),
  saveStatus: app.querySelector('[data-role="save-status"]'),
  backdrop: app.querySelector('[data-role="dialog-backdrop"]'),
  dialogTitle: app.querySelector('[data-role="dialog-title"]'),
  dialogText: app.querySelector('[data-role="dialog-text"]'),
  dialogCancel: app.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: app.querySelector('[data-role="dialog-confirm"]')
};

let habits = [];
let pendingDeleteId = null;
let dialogResolver = null;

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayKey(date) {
  const d = date || new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function formatTodayLabel() {
  const d = new Date();
  const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 " + weekdays[d.getDay()];
}

function normalizeHabit(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const dates = Array.isArray(source.completedDates)
    ? source.completedDates.filter((item) => typeof item === "string")
    : [];
  return Object.assign({}, source, {
    id: typeof source.id === "string" && source.id ? source.id : "habit-" + Date.now() + "-" + Math.random().toString(36).slice(2, 8),
    name: typeof source.name === "string" ? source.name : "",
    createdAt: typeof source.createdAt === "string" ? source.createdAt : new Date().toISOString(),
    completedDates: Array.from(new Set(dates))
  });
}

function normalizeState(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const list = Array.isArray(source.habits) ? source.habits.map(normalizeHabit) : [];
  return Object.assign({}, source, { habits: list });
}

function isDoneToday(habit) {
  return habit.completedDates.indexOf(todayKey()) !== -1;
}

function setSaveStatus(message, isError) {
  els.saveStatus.textContent = message || "";
  els.saveStatus.classList.toggle("is-error", Boolean(isError));
}

async function persist(nextHabits) {
  const current = await appStore.getState();
  const base = current && typeof current === "object" ? current : {};
  const next = Object.assign({}, base, { habits: nextHabits });
  await appStore.setState(next);
}

function renderStats() {
  const total = habits.length;
  const done = habits.filter(isDoneToday).length;
  const rate = total === 0 ? 0 : Math.round((done / total) * 100);
  els.statDone.textContent = String(done);
  els.statTotal.textContent = String(total);
  els.statRate.textContent = rate + "%";
  els.listCount.textContent = "共 " + total + " 个";
  els.emptyHint.hidden = total !== 0;
}

function buildHabitItem(habit) {
  const done = isDoneToday(habit);
  const li = document.createElement("li");
  li.className = "habit-item" + (done ? " is-done" : "");
  li.dataset.habitId = habit.id;

  const label = document.createElement("label");
  label.className = "habit-check";

  const checkbox = document.createElement("input");
  checkbox.type = "checkbox";
  checkbox.className = "habit-checkbox";
  checkbox.checked = done;
  checkbox.dataset.role = "toggle";
  checkbox.dataset.habitId = habit.id;
  checkbox.setAttribute("aria-label", "标记今天已完成：" + habit.name);

  const name = document.createElement("span");
  name.className = "habit-name";
  name.textContent = habit.name;

  label.appendChild(checkbox);
  label.appendChild(name);

  const meta = document.createElement("span");
  meta.className = "habit-meta";
  meta.textContent = "累计 " + habit.completedDates.length + " 天";

  const del = document.createElement("button");
  del.type = "button";
  del.className = "habit-delete";
  del.dataset.role = "delete";
  del.dataset.habitId = habit.id;
  del.textContent = "删除";

  li.appendChild(label);
  li.appendChild(meta);
  li.appendChild(del);
  return li;
}

function renderList() {
  els.list.textContent = "";
  habits.forEach((habit) => {
    els.list.appendChild(buildHabitItem(habit));
  });
}

function renderAll() {
  renderStats();
  renderList();
}

function openConfirmDialog(title, text) {
  els.dialogTitle.textContent = title;
  els.dialogText.textContent = text;
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
  return new Promise((resolve) => {
    dialogResolver = resolve;
  });
}

function closeConfirmDialog(result) {
  els.backdrop.hidden = true;
  const resolver = dialogResolver;
  dialogResolver = null;
  if (resolver) {
    resolver(result);
  }
}

async function addHabit(name) {
  const trimmed = name.trim();
  if (!trimmed) {
    els.formError.textContent = "请输入习惯名称。";
    els.nameInput.focus();
    return;
  }
  const duplicate = habits.some((habit) => habit.name === trimmed);
  if (duplicate) {
    els.formError.textContent = "已存在同名习惯，请换一个名称。";
    els.nameInput.focus();
    return;
  }
  els.formError.textContent = "";
  const next = habits.concat([
    {
      id: "habit-" + Date.now() + "-" + Math.random().toString(36).slice(2, 8),
      name: trimmed,
      createdAt: new Date().toISOString(),
      completedDates: []
    }
  ]);
  try {
    await persist(next);
    habits = next;
    els.nameInput.value = "";
    renderAll();
    setSaveStatus("已保存。", false);
  } catch (error) {
    setSaveStatus("保存失败，请重试。", true);
  }
}

async function toggleHabit(id, checked) {
  const key = todayKey();
  const next = habits.map((habit) => {
    if (habit.id !== id) {
      return habit;
    }
    const dates = habit.completedDates.slice();
    const index = dates.indexOf(key);
    if (checked && index === -1) {
      dates.push(key);
    } else if (!checked && index !== -1) {
      dates.splice(index, 1);
    }
    return Object.assign({}, habit, { completedDates: dates });
  });
  try {
    await persist(next);
    habits = next;
    renderAll();
    setSaveStatus("已保存。", false);
  } catch (error) {
    renderAll();
    setSaveStatus("保存失败，请重试。", true);
  }
}

async function removeHabit(id) {
  const target = habits.find((habit) => habit.id === id);
  if (!target) {
    return;
  }
  const confirmed = await openConfirmDialog("确认删除", "确定要删除习惯「" + target.name + "」吗？该习惯的打卡记录也会一并删除。");
  if (!confirmed) {
    return;
  }
  const next = habits.filter((habit) => habit.id !== id);
  try {
    await persist(next);
    habits = next;
    renderAll();
    setSaveStatus("已删除。", false);
  } catch (error) {
    setSaveStatus("删除失败，请重试。", true);
  }
}

async function init() {
  els.todayText.textContent = formatTodayLabel();

  const state = await appStore.getState();
  const normalized = normalizeState(state);
  habits = normalized.habits;

  if (!state || typeof state !== "object" || !Array.isArray(state.habits)) {
    try {
      await persist(habits);
    } catch (error) {
      setSaveStatus("初始化保存失败，请刷新重试。", true);
    }
  }

  renderAll();

  els.form.addEventListener("submit", async (event) => {
    event.preventDefault();
    await addHabit(els.nameInput.value);
  });

  els.nameInput.addEventListener("input", () => {
    if (els.formError.textContent) {
      els.formError.textContent = "";
    }
  });

  els.list.addEventListener("change", async (event) => {
    const target = event.target;
    if (!(target instanceof HTMLInputElement) || target.dataset.role !== "toggle") {
      return;
    }
    await toggleHabit(target.dataset.habitId, target.checked);
  });

  els.list.addEventListener("click", async (event) => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) {
      return;
    }
    const button = target.closest('[data-role="delete"]');
    if (!button) {
      return;
    }
    await removeHabit(button.dataset.habitId);
  });

  els.dialogCancel.addEventListener("click", () => {
    closeConfirmDialog(false);
  });

  els.dialogConfirm.addEventListener("click", () => {
    closeConfirmDialog(true);
  });

  els.backdrop.addEventListener("click", (event) => {
    if (event.target === els.backdrop) {
      closeConfirmDialog(false);
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !els.backdrop.hidden) {
      closeConfirmDialog(false);
    }
  });
}

await init();

