:root {
  --bg-deep: #0f172a;
  --bg-mid: #16233c;
  --panel: rgba(30, 44, 71, 0.86);
  --panel-border: rgba(120, 160, 220, 0.22);
  --text-main: #eaf1fb;
  --text-soft: #a8bad4;
  --accent: #4ade80;
  --accent-strong: #22c55e;
  --accent-ink: #06281a;
  --danger: #f87171;
  --danger-strong: #ef4444;
  --focus: #7dd3fc;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  background: var(--bg-deep);
  color: var(--text-main);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, "Segoe UI", sans-serif;
}

#app {
  min-height: 100vh;
  background:
    radial-gradient(1100px 620px at 12% -8%, rgba(74, 222, 128, 0.16), transparent 62%),
    radial-gradient(900px 560px at 96% 4%, rgba(125, 211, 252, 0.14), transparent 60%),
    linear-gradient(170deg, var(--bg-deep) 0%, var(--bg-mid) 55%, #101a2e 100%);
  color: var(--text-main);
}

.app-shell {
  box-sizing: border-box;
  min-height: 100vh;
  width: 100%;
  max-width: 780px;
  margin: 0 auto;
  padding: 32px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.app-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.app-title {
  margin: 0;
  font-size: 30px;
  letter-spacing: 2px;
  color: var(--text-main);
}

.app-subtitle {
  margin: 0;
  font-size: 14px;
  color: var(--text-soft);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 16px;
  padding: 18px 20px;
  box-shadow: 0 14px 34px rgba(4, 10, 22, 0.42);
  backdrop-filter: blur(6px);
}

.stats-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 22px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 84px;
}

.stat-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--accent);
  line-height: 1.1;
}

.stat-label {
  font-size: 12px;
  color: var(--text-soft);
}

.stat-divider {
  width: 1px;
  height: 34px;
  background: var(--panel-border);
}

.today-line {
  margin: 0;
  margin-left: auto;
  font-size: 13px;
  color: var(--text-soft);
}

.today-line span {
  color: var(--text-main);
  font-weight: 600;
}

.habit-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 240px;
}

.field-label {
  font-size: 13px;
  color: var(--text-soft);
}

.field-input {
  box-sizing: border-box;
  width: 100%;
  padding: 11px 13px;
  font-size: 15px;
  color: var(--text-main);
  background: rgba(12, 20, 36, 0.85);
  border: 1px solid var(--panel-border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field-input::placeholder {
  color: rgba(168, 186, 212, 0.6);
}

.field-input:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.22);
}

.btn {
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  padding: 11px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.15s ease, border-color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-primary {
  background: var(--accent-strong);
  color: var(--accent-ink);
}

.btn-primary:hover {
  background: var(--accent);
}

.btn-ghost {
  background: transparent;
  color: var(--text-soft);
  border-color: var(--panel-border);
}

.btn-ghost:hover {
  color: var(--text-main);
  border-color: var(--focus);
}

.btn-danger {
  background: var(--danger-strong);
  color: #2a0606;
}

.btn-danger:hover {
  background: var(--danger);
}

.form-error {
  margin: 10px 0 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.list-title {
  margin: 0;
  font-size: 17px;
  color: var(--text-main);
}

.list-count {
  font-size: 13px;
  color: var(--text-soft);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(12, 20, 36, 0.6);
  border: 1px solid var(--panel-border);
}

.habit-item.is-done {
  border-color: rgba(74, 222, 128, 0.55);
  background: rgba(34, 197, 94, 0.12);
}

.habit-check {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  cursor: pointer;
  min-width: 0;
}

.habit-checkbox {
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  accent-color: var(--accent-strong);
  cursor: pointer;
}

.habit-name {
  font-size: 15px;
  color: var(--text-main);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
}

.habit-meta {
  font-size: 12px;
  color: var(--text-soft);
  white-space: nowrap;
}

.habit-delete {
  font-family: inherit;
  font-size: 13px;
  padding: 7px 12px;
  border-radius: 9px;
  border: 1px solid rgba(248, 113, 113, 0.45);
  background: transparent;
  color: var(--danger);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.habit-delete:hover {
  background: rgba(248, 113, 113, 0.16);
}

.empty-hint {
  margin: 4px 0 0;
  font-size: 14px;
  color: var(--text-soft);
}

.empty-hint[hidden] {
  display: none;
}

.save-status {
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--text-soft);
}

.save-status.is-error {
  color: var(--danger);
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 11, 22, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: #1b2a45;
  border: 1px solid var(--panel-border);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 22px 48px rgba(3, 8, 18, 0.6);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--text-main);
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 22px 14px 44px;
  }
  .today-line {
    margin-left: 0;
  }
  .stat-divider {
    display: none;
  }
}
